import React, { useState, useMemo } from "react";
import { Filter } from "lucide-react";
import StatusBadge from "../components/StatusBadge";
import { TRANSACTIONS } from "../data/mockData";
import { Category, TransactionStatus } from "../types";

const CATEGORIES: string[] = [
  "All Categories",
  "Income",
  "Food",
  "Housing",
  "Transport",
  "Entertainment",
  "Shopping",
  "Health",
];

const STATUSES: string[] = ["All Status", "completed", "pending", "flagged"];

const PER_PAGE = 6;

const CATEGORY_ICONS: Record<string, string> = {
  Income: "💰",
  Food: "🛒",
  Housing: "🏠",
  Entertainment: "🎬",
  Transport: "🚗",
  Shopping: "🛍️",
  Health: "💊",
};

const Transactions: React.FC = () => {
  const [catFilter, setCatFilter] = useState("All Categories");
  const [statusFilter, setStatusFilter] = useState("All Status");
  const [dateFrom, setDateFrom] = useState("2024-06-01");
  const [dateTo, setDateTo] = useState("2024-06-15");
  const [page, setPage] = useState(1);

  const filtered = useMemo(() => {
    return TRANSACTIONS.filter((tx) => {
      const matchCat = catFilter === "All Categories" || tx.category === catFilter;
      const matchStatus = statusFilter === "All Status" || tx.status === statusFilter;
      const matchDate = tx.date >= dateFrom && tx.date <= dateTo;
      return matchCat && matchStatus && matchDate;
    });
  }, [catFilter, statusFilter, dateFrom, dateTo]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));
  const paged = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const handleFilter = (setter: (v: string) => void) => (e: React.ChangeEvent<HTMLSelectElement | HTMLInputElement>) => {
    setter(e.target.value);
    setPage(1);
  };

  return (
    <div className="p-4 md:p-6 max-w-6xl mx-auto">
      <div className="mb-5">
        <h1 className="text-xl font-medium text-gray-900">Transaction Ledger</h1>
        <p className="text-sm text-gray-400 mt-0.5">{filtered.length} transactions found</p>
      </div>

      <div className="bg-white border border-gray-100 rounded-xl p-5">
        {/* Filters */}
        <div className="flex flex-wrap items-center gap-3 mb-5 pb-4 border-b border-gray-50">
          <Filter size={15} className="text-gray-400 shrink-0" />
          <select
            value={catFilter}
            onChange={handleFilter(setCatFilter)}
            className="text-sm border border-gray-200 rounded-lg px-3 py-1.5 bg-white focus:outline-none focus:border-emerald-400"
          >
            {CATEGORIES.map((c) => <option key={c}>{c}</option>)}
          </select>
          <select
            value={statusFilter}
            onChange={handleFilter(setStatusFilter)}
            className="text-sm border border-gray-200 rounded-lg px-3 py-1.5 bg-white focus:outline-none focus:border-emerald-400 capitalize"
          >
            {STATUSES.map((s) => <option key={s}>{s}</option>)}
          </select>
          <input
            type="date"
            value={dateFrom}
            onChange={handleFilter(setDateFrom)}
            className="text-sm border border-gray-200 rounded-lg px-3 py-1.5 focus:outline-none focus:border-emerald-400"
          />
          <span className="text-gray-300 text-sm">→</span>
          <input
            type="date"
            value={dateTo}
            onChange={handleFilter(setDateTo)}
            className="text-sm border border-gray-200 rounded-lg px-3 py-1.5 focus:outline-none focus:border-emerald-400"
          />
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-100">
                {["Status", "Date", "Description", "Category", "Method", "Amount"].map((h) => (
                  <th
                    key={h}
                    className="text-left py-3 px-3 text-xs font-medium text-gray-400 uppercase tracking-wide"
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {paged.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-10 text-center text-gray-400 text-sm">
                    No transactions match your filters.
                  </td>
                </tr>
              ) : (
                paged.map((tx) => (
                  <tr key={tx.id} className="border-b border-gray-50 hover:bg-gray-50 transition-colors">
                    <td className="py-3 px-3">
                      <StatusBadge status={tx.status} />
                    </td>
                    <td className="py-3 px-3 text-gray-500">{tx.date}</td>
                    <td className="py-3 px-3">
                      <div className="flex items-center gap-2">
                        <span>{CATEGORY_ICONS[tx.category] ?? "💳"}</span>
                        <span className="font-medium text-gray-800">{tx.description}</span>
                      </div>
                    </td>
                    <td className="py-3 px-3">
                      <span className="bg-gray-100 text-gray-600 text-xs px-2 py-1 rounded-md">
                        {tx.category}
                      </span>
                    </td>
                    <td className="py-3 px-3 text-gray-500">{tx.method}</td>
                    <td
                      className={`py-3 px-3 font-semibold text-right ${
                        tx.amount > 0 ? "text-emerald-600" : "text-red-500"
                      }`}
                    >
                      {tx.amount > 0 ? "+" : "-"}${Math.abs(tx.amount).toFixed(2)}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between mt-4 pt-4 border-t border-gray-50">
          <p className="text-xs text-gray-400">
            Showing {filtered.length === 0 ? 0 : (page - 1) * PER_PAGE + 1}–
            {Math.min(page * PER_PAGE, filtered.length)} of {filtered.length}
          </p>
          <div className="flex gap-1">
            <button
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page === 1}
              className="px-3 py-1.5 text-xs border border-gray-200 rounded-lg hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              ‹
            </button>
            {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
              <button
                key={n}
                onClick={() => setPage(n)}
                className={`px-3 py-1.5 text-xs rounded-lg border transition-colors ${
                  page === n
                    ? "bg-emerald-500 text-white border-emerald-500"
                    : "border-gray-200 hover:bg-gray-50"
                }`}
              >
                {n}
              </button>
            ))}
            <button
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="px-3 py-1.5 text-xs border border-gray-200 rounded-lg hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              ›
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Transactions;
